// Move mail — the IMAP trigger cannot move a message: its Action field offers
// "None" and "Mark as Read" and nothing else, while the Lastenheft asks for the
// processed mail to land in a folder. So a Code node does the move. It needs
// NODE_FUNCTION_ALLOW_EXTERNAL=imap on the container.
// This code sits in three nodes, identical except for TARGET_FOLDER — n8n has
// no shared code library between Code nodes, so the duplication is deliberate.
// A failed move must not fail the run: the ticket exists, only the mail sits in
// the wrong folder. The error is returned as data instead of thrown.
// Runs once for all items.

const Imap = require('imap');

const TARGET_FOLDER = 'INBOX.erledigt';
const IMAP_HOST = 'mail.your-server.de';
const IMAP_PORT = 993;
const AUTH_TIMEOUT = 10000;

const uid = Number($('Guard: filter, quota, extract').first().json.messageUid);

/**
 * Reads the mailbox credentials from the container environment. They never go
 * into the workflow JSON, because that file is committed to the repository.
 * @returns {Object} user and password
 */
function readCredentials() {
  const user = $env.JOIN_IMAP_USER;
  const password = $env.JOIN_IMAP_PASSWORD;
  if (!user || !password) {
    throw new Error('JOIN_IMAP_USER and JOIN_IMAP_PASSWORD are not set on the n8n container');
  }
  return { user, password };
}

/**
 * Builds the IMAP client from the environment credentials.
 * @returns {Object} An unconnected imap client
 */
function createConnection() {
  const credentials = readCredentials();
  return new Imap({
    user: credentials.user,
    password: credentials.password,
    host: IMAP_HOST,
    port: IMAP_PORT,
    tls: true,
    authTimeout: AUTH_TIMEOUT,
  });
}

/**
 * Returns a callback that ends the connection exactly once and then settles the
 * surrounding promise. Without the end() the socket stays open and the mailbox
 * eventually refuses new connections.
 * @param {Object} connection - The imap client
 * @param {Function} resolve - Promise resolve
 * @param {Function} reject - Promise reject
 * @returns {Function} The finishing callback
 */
function buildFinisher(connection, resolve, reject) {
  let settled = false;
  return (error) => {
    if (settled) return;
    settled = true;
    try {
      connection.end();
    } catch (endError) {
      // The connection was already gone; nothing left to close.
    }
    if (error) return reject(error);
    resolve();
  };
}

/**
 * Opens the inbox for writing and moves the message.
 * @param {Object} connection - The ready imap client
 * @param {number} messageUid - The UID to move
 * @param {Function} finish - Callback that ends the connection
 */
function runMove(connection, messageUid, finish) {
  connection.openBox('INBOX', false, (openError) => {
    if (openError) return finish(openError);
    connection.move(String(messageUid), TARGET_FOLDER, (moveError) => finish(moveError || null));
  });
}

/**
 * Opens an IMAP connection and moves one message to the target folder.
 * @param {number} messageUid - The UID the trigger reported
 * @returns {Promise<void>} Resolves once the move is acknowledged
 */
function moveMessage(messageUid) {
  return new Promise((resolve, reject) => {
    const connection = createConnection();
    const finish = buildFinisher(connection, resolve, reject);
    connection.once('ready', () => runMove(connection, messageUid, finish));
    connection.once('error', finish);
    connection.connect();
  });
}

/**
 * Builds the single item this node returns, in success and failure alike.
 * @param {string} error - The error text, empty when the move worked
 * @returns {Array<Object>} The n8n item list
 */
function report(error) {
  return [{ json: { moved: error === '', folder: TARGET_FOLDER, uid: uid || null, error } }];
}

// --- main -------------------------------------------------------------------
if (!Number.isInteger(uid) || uid <= 0) {
  return report('no message uid available, the mail was left in INBOX');
}

try {
  await moveMessage(uid);
  return report('');
} catch (error) {
  return report(String((error && error.message) || error));
}

// Move mail — the IMAP trigger cannot move a message: its Action field offers
// "None" and "Mark as Read" and nothing else, while the Lastenheft asks for the
// processed mail to land in a folder. So a Code node does the move. It needs
// NODE_FUNCTION_ALLOW_EXTERNAL=imap on the container.
// This code sits in three nodes, identical except for TARGET_FOLDER — n8n has
// no shared code library between Code nodes, so the duplication is deliberate.
// A failed move must not fail the run: the ticket exists, only the mail sits in
// the wrong folder. The error is returned as data instead of thrown.
// Runs once for all items.

const Imap = require('imap');

const TARGET_FOLDER = 'INBOX.zu-bearbeiten';
const IMAP_HOST = 'mail.your-server.de';
const IMAP_PORT = 993;
const AUTH_TIMEOUT = 10000;

const uid = Number($('Guard: filter, quota, extract').first().json.messageUid);

/**
 * Reads the mailbox credentials from the container environment. They never go
 * into the workflow JSON, because that file is committed to the repository.
 * @returns {Object} user and password
 */
function readCredentials() {
  const user = $env.JOIN_IMAP_USER;
  const password = $env.JOIN_IMAP_PASSWORD;
  if (!user || !password) {
    throw new Error('JOIN_IMAP_USER and JOIN_IMAP_PASSWORD are not set on the n8n container');
  }
  return { user, password };
}

/**
 * Builds the IMAP client from the environment credentials.
 * @returns {Object} An unconnected imap client
 */
function createConnection() {
  const credentials = readCredentials();
  return new Imap({
    user: credentials.user,
    password: credentials.password,
    host: IMAP_HOST,
    port: IMAP_PORT,
    tls: true,
    authTimeout: AUTH_TIMEOUT,
  });
}

/**
 * Returns a callback that ends the connection exactly once and then settles the
 * surrounding promise. Without the end() the socket stays open and the mailbox
 * eventually refuses new connections.
 * @param {Object} connection - The imap client
 * @param {Function} resolve - Promise resolve
 * @param {Function} reject - Promise reject
 * @returns {Function} The finishing callback
 */
function buildFinisher(connection, resolve, reject) {
  let settled = false;
  return (error) => {
    if (settled) return;
    settled = true;
    try {
      connection.end();
    } catch (endError) {
      // The connection was already gone; nothing left to close.
    }
    if (error) return reject(error);
    resolve();
  };
}

/**
 * Opens the inbox for writing and moves the message.
 * @param {Object} connection - The ready imap client
 * @param {number} messageUid - The UID to move
 * @param {Function} finish - Callback that ends the connection
 */
function runMove(connection, messageUid, finish) {
  connection.openBox('INBOX', false, (openError) => {
    if (openError) return finish(openError);
    connection.move(String(messageUid), TARGET_FOLDER, (moveError) => finish(moveError || null));
  });
}

/**
 * Opens an IMAP connection and moves one message to the target folder.
 * @param {number} messageUid - The UID the trigger reported
 * @returns {Promise<void>} Resolves once the move is acknowledged
 */
function moveMessage(messageUid) {
  return new Promise((resolve, reject) => {
    const connection = createConnection();
    const finish = buildFinisher(connection, resolve, reject);
    connection.once('ready', () => runMove(connection, messageUid, finish));
    connection.once('error', finish);
    connection.connect();
  });
}

/**
 * Builds the single item this node returns, in success and failure alike.
 * @param {string} error - The error text, empty when the move worked
 * @returns {Array<Object>} The n8n item list
 */
function report(error) {
  return [{ json: { moved: error === '', folder: TARGET_FOLDER, uid: uid || null, error } }];
}

// --- main -------------------------------------------------------------------
if (!Number.isInteger(uid) || uid <= 0) {
  return report('no message uid available, the mail was left in INBOX');
}

try {
  await moveMessage(uid);
  return report('');
} catch (error) {
  return report(String((error && error.message) || error));
}

